private SqlReverseResult multiTableDeleteResult() {
    return res("user", null, List.<Condition>of(new Condition.Simple(col("t", "status"), "=", lit("1"), null)), List.<OrderByItem>of(), null, List.<String>of(), ReverseStatementKind.DELETE, List.<ReverseSet>of(), List.<String>of(), List.<List<SqlValue>>of(), List.<ReverseJoin>of(new ReverseJoin(JoinType.LEFT, "address", "t1", List.<Condition>of(new Condition.ColumnComparison(col("t1", "user_id"), col("t", "id"), null)), null, null)), List.<String>of("t", "t1"));
}@Test public void DELETE_多表_生成DeleteJoinWrapper与join链() {
JavaCodeGenerator.EntityTarget main = new JavaCodeGenerator.EntityTarget("User", Map.of("id", "id", "status", "status"), Map.of("t1", new JavaCodeGenerator.EntityTarget("Address", Map.of("user_id", "userId"))));String code = JavaCodeGenerator.generate(multiTableDeleteResult(), main, GeneratedWrapper.MPJ_LAMBDA, null);assertTrue(code, code.contains("new DeleteJoinWrapper<>(User.class)"));assertTrue(code, code.contains(".delete(\"t\", \"t1\")"));assertTrue(code, code.contains(".leftJoin(Address.class, Address::getUserId, User::getId)"));assertTrue(code, code.contains(".eq(User::getStatus, 1)"));assertTrue(code, code.contains("（MPJ 形态）"));}
@Test public void DELETE_多表_副实体缺失_报错() {
SqlReverseResult result = multiTableDeleteResult();JavaCodeGenerator.EntityTarget main = new JavaCodeGenerator.EntityTarget("User", Map.of("id", "id", "status", "status"));SqlReverseException ex;
try {
JavaCodeGenerator.generate(result, main, GeneratedWrapper.MPJ_LAMBDA, null);throw new AssertionError("expected SqlReverseException");} catch (SqlReverseException e) {
    ex = e;
}
assertTrue(ex.getDetail(), ex.getDetail().contains("无法映射为 lambda join"));}
@Test public void DELETE_多表_主实体不可用_报错() {
SqlReverseException ex;
try {
JavaCodeGenerator.generate(multiTableDeleteResult(), null, GeneratedWrapper.QUERY, null);throw new AssertionError("expected SqlReverseException");} catch (SqlReverseException e) {
    ex = e;
}
assertEquals(SqlReverseParser.KEY_UNSUPPORTED, ex.getKey());assertTrue(ex.getDetail().contains("多表删除需要实体类上下文"));}
